#!/usr/bin/env python3
"""Patch a project generated by `solana-mobile webshell init` (0.6.0) for Connex.

Adds what the stock shell lacks:
  * camera for getUserMedia (QR scanning), granted only to pages on the app's own host;
  * <input type=file> support (profile photo upload);
  * App Links + NFC: https://<host>/u/... and /e/... open inside the app.

Usage: python3 scripts/patch-webshell.py android
Idempotent: refuses to patch twice (looks for a marker).
"""
import pathlib
import re
import sys

MARKER = "CONNEX_PATCH"


def replace_once(text: str, old: str, new: str, where: str) -> str:
    count = text.count(old)
    if count != 1:
        sys.exit(f"anchor not found exactly once in {where} ({count}x): {old[:70]!r}")
    return text.replace(old, new)


def main() -> None:
    root = pathlib.Path(sys.argv[1]).resolve()
    app = root / "app"
    gradle = app / "build.gradle.kts"
    manifest = app / "src/main/AndroidManifest.xml"
    gradle_text = gradle.read_text()
    match = re.search(r'namespace = "([^"]+)"', gradle_text)
    if match is None:
        sys.exit("namespace not found in app/build.gradle.kts")
    pkg = match.group(1)
    src = app / "src/main/java" / pkg.replace(".", "/")
    main_kt = src / "MainActivity.kt"
    chrome_kt = src / "WebShellChromeClient.kt"

    if MARKER in main_kt.read_text():
        print("already patched")
        return

    # --- build.gradle.kts: expose the web host to the manifest -------------------------
    # (inside android {} the name `java` resolves to the Java extension, so no java.net.URI here)
    gradle_text = replace_once(
        gradle_text,
        "        buildConfigField(\"String\", \"SOLANA_MOBILE_URL\"",
        "        // CONNEX_PATCH: host used by the App Links / NFC intent filters.\n"
        "        manifestPlaceholders[\"webHost\"] =\n"
        "            webShellUrl.substringAfter(\"://\").substringBefore(\"/\").substringBefore(\":\")\n"
        "        buildConfigField(\"String\", \"SOLANA_MOBILE_URL\"",
        "build.gradle.kts",
    )
    gradle.write_text(gradle_text)

    # --- AndroidManifest.xml -------------------------------------------------------------
    m = manifest.read_text()
    m = replace_once(
        m,
        '    <uses-permission android:name="android.permission.INTERNET" />\n',
        '    <uses-permission android:name="android.permission.INTERNET" />\n'
        "    <!-- CONNEX_PATCH: camera for QR scanning; NFC optional -->\n"
        '    <uses-permission android:name="android.permission.CAMERA" />\n'
        '    <uses-feature android:name="android.hardware.camera" android:required="false" />\n'
        '    <uses-feature android:name="android.hardware.nfc" android:required="false" />\n',
        "AndroidManifest.xml",
    )
    m = replace_once(
        m,
        '            android:exported="true"\n',
        '            android:exported="true"\n            android:launchMode="singleTask"\n',
        "AndroidManifest.xml",
    )
    m = replace_once(
        m,
        "                <category android:name=\"android.intent.category.LAUNCHER\" />\n"
        "            </intent-filter>\n",
        "                <category android:name=\"android.intent.category.LAUNCHER\" />\n"
        "            </intent-filter>\n"
        "            <!-- CONNEX_PATCH: profile and event links open in the app (verified App Links) -->\n"
        '            <intent-filter android:autoVerify="true">\n'
        '                <action android:name="android.intent.action.VIEW" />\n'
        '                <category android:name="android.intent.category.DEFAULT" />\n'
        '                <category android:name="android.intent.category.BROWSABLE" />\n'
        '                <data android:scheme="https" android:host="${webHost}" />\n'
        '                <data android:pathPrefix="/u/" />\n'
        '                <data android:pathPrefix="/e/" />\n'
        "            </intent-filter>\n"
        "            <!-- CONNEX_PATCH: NFC tags/stickers with a Connex profile link -->\n"
        "            <intent-filter>\n"
        '                <action android:name="android.nfc.action.NDEF_DISCOVERED" />\n'
        '                <category android:name="android.intent.category.DEFAULT" />\n'
        '                <data android:scheme="https" android:host="${webHost}" android:pathPrefix="/u/" />\n'
        "            </intent-filter>\n",
        "AndroidManifest.xml",
    )
    manifest.write_text(m)

    # --- WebShellChromeClient.kt: camera + file chooser hooks ----------------------------
    c = chrome_kt.read_text()
    c = replace_once(c, "import android.content.Intent\n", "import android.content.Intent\nimport android.net.Uri\n", "WebShellChromeClient.kt")
    c = replace_once(
        c,
        "import android.webkit.ConsoleMessage\n",
        "import android.webkit.ConsoleMessage\nimport android.webkit.PermissionRequest\nimport android.webkit.ValueCallback\n",
        "WebShellChromeClient.kt",
    )
    c = replace_once(
        c,
        "    private val isDebug: Boolean,\n) : WebChromeClient() {\n",
        "    private val isDebug: Boolean,\n"
        "    // CONNEX_PATCH: camera and file chooser are delegated to the activity.\n"
        "    private val scopeHostProvider: () -> String,\n"
        "    private val onCameraRequest: (PermissionRequest) -> Unit,\n"
        "    private val onFileChooser: (ValueCallback<Array<Uri>>, FileChooserParams) -> Boolean,\n"
        ") : WebChromeClient() {\n"
        "    override fun onPermissionRequest(request: PermissionRequest) {\n"
        "        // Only pages on the app's own host may use the camera, and only the camera.\n"
        "        val fromScope = request.origin?.host.equals(scopeHostProvider.invoke(), ignoreCase = true)\n"
        "        val wantsCamera = request.resources.contains(PermissionRequest.RESOURCE_VIDEO_CAPTURE)\n"
        "        if (fromScope && wantsCamera) onCameraRequest(request) else request.deny()\n"
        "    }\n\n"
        "    override fun onShowFileChooser(\n"
        "        webView: WebView,\n"
        "        filePathCallback: ValueCallback<Array<Uri>>,\n"
        "        fileChooserParams: FileChooserParams,\n"
        "    ): Boolean = onFileChooser(filePathCallback, fileChooserParams)\n\n",
        "WebShellChromeClient.kt",
    )
    chrome_kt.write_text(c)

    # --- MainActivity.kt -----------------------------------------------------------------
    k = main_kt.read_text()
    k = replace_once(
        k,
        "import android.annotation.SuppressLint\n",
        "import android.Manifest\n"
        "import android.annotation.SuppressLint\n"
        "import android.content.ActivityNotFoundException\n"
        "import android.content.pm.PackageManager\n"
        "import android.net.Uri\n"
        "import android.webkit.PermissionRequest\n"
        "import android.webkit.ValueCallback\n"
        "import android.webkit.WebChromeClient\n"
        "import androidx.activity.result.contract.ActivityResultContracts\n"
        "import androidx.compose.runtime.LaunchedEffect\n"
        "import androidx.core.content.ContextCompat\n",
        "MainActivity.kt",
    )
    k = replace_once(
        k,
        "class MainActivity : ComponentActivity() {\n"
        "    override fun onCreate(savedInstanceState: Bundle?) {\n"
        "        installSplashScreen()\n"
        "        super.onCreate(savedInstanceState)\n",
        "class MainActivity : ComponentActivity() {\n"
        "    // CONNEX_PATCH: camera permission, file chooser and deep links.\n"
        "    private var pendingPermission: PermissionRequest? = null\n"
        "    private var pendingFileCallback: ValueCallback<Array<Uri>>? = null\n"
        "    private val newDeepLink = mutableStateOf<String?>(null)\n\n"
        "    private val cameraPermissionLauncher =\n"
        "        registerForActivityResult(ActivityResultContracts.RequestPermission()) { granted ->\n"
        "            val request = pendingPermission ?: return@registerForActivityResult\n"
        "            pendingPermission = null\n"
        "            if (granted) request.grant(arrayOf(PermissionRequest.RESOURCE_VIDEO_CAPTURE)) else request.deny()\n"
        "        }\n\n"
        "    private val fileChooserLauncher =\n"
        "        registerForActivityResult(ActivityResultContracts.StartActivityForResult()) { result ->\n"
        "            val callback = pendingFileCallback ?: return@registerForActivityResult\n"
        "            pendingFileCallback = null\n"
        "            callback.onReceiveValue(WebChromeClient.FileChooserParams.parseResult(result.resultCode, result.data))\n"
        "        }\n\n"
        "    fun handleCameraRequest(request: PermissionRequest) {\n"
        "        if (ContextCompat.checkSelfPermission(this, Manifest.permission.CAMERA) == PackageManager.PERMISSION_GRANTED) {\n"
        "            request.grant(arrayOf(PermissionRequest.RESOURCE_VIDEO_CAPTURE))\n"
        "        } else {\n"
        "            pendingPermission?.deny()\n"
        "            pendingPermission = request\n"
        "            cameraPermissionLauncher.launch(Manifest.permission.CAMERA)\n"
        "        }\n"
        "    }\n\n"
        "    fun handleFileChooser(\n"
        "        callback: ValueCallback<Array<Uri>>,\n"
        "        params: WebChromeClient.FileChooserParams,\n"
        "    ): Boolean {\n"
        "        pendingFileCallback?.onReceiveValue(null)\n"
        "        pendingFileCallback = callback\n"
        "        return try {\n"
        "            fileChooserLauncher.launch(params.createIntent())\n"
        "            true\n"
        "        } catch (_: ActivityNotFoundException) {\n"
        "            pendingFileCallback = null\n"
        "            false\n"
        "        }\n"
        "    }\n\n"
        "    override fun onCreate(savedInstanceState: Bundle?) {\n"
        "        installSplashScreen()\n"
        "        super.onCreate(savedInstanceState)\n"
        "        val initialDeepLink = intent?.dataString\n"
        "        addOnNewIntentListener { newIntent -> newDeepLink.value = newIntent.dataString }\n",
        "MainActivity.kt",
    )
    k = replace_once(
        k,
        "                WebShellScreen()\n",
        "                WebShellScreen(\n"
        "                    host = this,\n"
        "                    initialDeepLink = initialDeepLink,\n"
        "                    newDeepLink = newDeepLink.value,\n"
        "                    onNewDeepLinkHandled = { newDeepLink.value = null },\n"
        "                )\n",
        "MainActivity.kt",
    )
    k = replace_once(
        k,
        "fun WebShellScreen() {\n"
        "    val context = LocalContext.current\n"
        "    val startUrl = remember { normalizeHttpUrl() }\n"
        "    if (startUrl == null) {\n"
        "        Log.e(TAG, \"SOLANA_MOBILE_URL is not a valid http(s) URL\")\n"
        "        return\n"
        "    }\n"
        "    val scopeHost = remember(startUrl) { startUrl.toUri().host.orEmpty() }\n",
        "fun WebShellScreen(\n"
        "    host: MainActivity,\n"
        "    initialDeepLink: String?,\n"
        "    newDeepLink: String?,\n"
        "    onNewDeepLinkHandled: () -> Unit,\n"
        ") {\n"
        "    val context = LocalContext.current\n"
        "    val homeUrl = remember { normalizeHttpUrl() }\n"
        "    if (homeUrl == null) {\n"
        "        Log.e(TAG, \"SOLANA_MOBILE_URL is not a valid http(s) URL\")\n"
        "        return\n"
        "    }\n"
        "    val scopeHost = remember(homeUrl) { homeUrl.toUri().host.orEmpty() }\n"
        "    val startUrl = remember(homeUrl) { inScopeHttpsUrl(initialDeepLink, scopeHost) ?: homeUrl }\n",
        "MainActivity.kt",
    )
    k = replace_once(
        k,
        "                        isDebug = BuildConfig.DEBUG,\n                    )\n",
        "                        isDebug = BuildConfig.DEBUG,\n"
        "                        scopeHostProvider = { scopeHost },\n"
        "                        onCameraRequest = { request -> host.handleCameraRequest(request) },\n"
        "                        onFileChooser = { callback, params -> host.handleFileChooser(callback, params) },\n"
        "                    )\n",
        "MainActivity.kt",
    )
    k = replace_once(
        k,
        "    BackHandler(enabled = webView.canGoBack()) {\n",
        "    LaunchedEffect(newDeepLink) {\n"
        "        val link = inScopeHttpsUrl(newDeepLink, scopeHost)\n"
        "        if (link != null) webView.loadUrl(link)\n"
        "        if (newDeepLink != null) onNewDeepLinkHandled()\n"
        "    }\n\n"
        "    BackHandler(enabled = webView.canGoBack()) {\n",
        "MainActivity.kt",
    )
    k = replace_once(
        k,
        "private fun normalizeHttpUrl(): String? {\n",
        "// CONNEX_PATCH: only https links on the app's own host are loaded from intents.\n"
        "private fun inScopeHttpsUrl(\n"
        "    candidate: String?,\n"
        "    scopeHost: String,\n"
        "): String? {\n"
        "    if (candidate.isNullOrBlank()) return null\n"
        "    val uri = candidate.toUri()\n"
        "    if (uri.scheme?.lowercase() != \"https\") return null\n"
        "    if (!uri.host.equals(scopeHost, ignoreCase = true)) return null\n"
        "    return uri.toString()\n"
        "}\n\n"
        "private fun normalizeHttpUrl(): String? {\n",
        "MainActivity.kt",
    )
    main_kt.write_text(k)
    print(f"patched {root} (package {pkg})")


if __name__ == "__main__":
    main()
